<?php

declare(strict_types=1);

namespace Vodnox\Telephony\Events;

/**
 * Extracts the SIP endpoint username from an Asterisk channel name.
 *
 * Channels created for our endpoints look like:
 *     PJSIP/vdx12_ab12cd34ef56-0000002a   (an employee's browser phone)
 *     PJSIP/vdg12_ab12cd34ef56-0000002a   (a GSM gateway line)
 * where the part before the suffix is the globally unique SIP username
 * generated by the application (SipCredentialService / GatewayCredentialService).
 *
 * Anything else — the legacy test endpoints (plain "1001"), trunks, local
 * channels, or the old `vodnox-test` context — is deliberately not managed, so
 * this service never emits events for a call it must not see.
 */
final class ChannelIdentity
{
    public const TECHNOLOGY = 'PJSIP/';

    /**
     * The two prefixes VODNOX allocates: "vdx" for employees, "vdg" for gateway
     * lines. Both are followed by the organization id and a random suffix.
     */
    private const MANAGED_PATTERN = '/^vd[xg][0-9]+_[a-z0-9]{8,64}$/';

    private const OWNER_PATTERN = '/^vd[xg]([0-9]+)_/';

    /**
     * @return array{username: string}|null
     */
    public static function parse(mixed $channel): ?array
    {
        if (! is_string($channel) || $channel === '') {
            return null;
        }

        $name = $channel;

        // Strip the per-call suffix Asterisk appends: "-0000002a".
        $stripped = preg_replace('/-[0-9a-fA-F]{4,}$/', '', $name);

        if (! is_string($stripped) || ! str_starts_with($stripped, self::TECHNOLOGY)) {
            return null;
        }

        $username = substr($stripped, strlen(self::TECHNOLOGY));

        if ($username === '' || str_contains($username, '/')) {
            return null;
        }

        return ['username' => $username];
    }

    /**
     * True only for endpoints provisioned by VODNOX: an employee phone
     * (vdx<organizationId>_<random>) or a GSM gateway line
     * (vdg<organizationId>_<random>).
     */
    public static function isManaged(mixed $channel): bool
    {
        $parsed = self::parse($channel);

        if ($parsed === null) {
            return false;
        }

        return preg_match(self::MANAGED_PATTERN, $parsed['username']) === 1;
    }

    /**
     * Whether the channel belongs to a GSM gateway line rather than an employee.
     */
    public static function isGateway(mixed $channel): bool
    {
        $parsed = self::parse($channel);

        return $parsed !== null && str_starts_with($parsed['username'], 'vdg');
    }

    /**
     * The organization id encoded in a managed endpoint, when present.
     */
    public static function organizationId(mixed $channel): ?int
    {
        $parsed = self::parse($channel);

        if ($parsed === null || preg_match(self::OWNER_PATTERN, $parsed['username'], $m) !== 1) {
            return null;
        }

        return (int) $m[1];
    }
}
